branch_walrus.source:
class Cell:
 def forward(self,emb,aug,enabled):
  selected = ((emb := aug), emb) if enabled else (emb, emb)
  consume(selected)

guard_walrus.source:
class Cell:
 def forward(self,emb,aug,enabled):
  selected = emb if (emb := aug) else aug
  consume(selected)

opaque_branches.source:
class Cell:
 def forward(self,emb,aug,enabled):
  selected = first(emb) if enabled else second(aug)
  consume(selected)

ordinary_conditioning.source:
class Cell:
 def forward(self,emb,aug,enabled):
  selected = emb + aug if enabled else emb
  consume(selected)
